create table public.exports (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, document_id uuid not null references public.documents(id) on delete cascade, format text not null check (format in ('pdf','docx','doc','html')), file_path text, created_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now());
create table public.subscriptions (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, plan text not null, monthly_quota integer not null default 60, status text not null default 'active' check (status in ('active','past_due','cancelled')), period_start date not null, period_end date not null, created_at timestamptz not null default now());
create table public.audit_events (id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles(id) on delete set null, organization_id uuid references public.organizations(id) on delete set null, action text not null, target_type text, target_id uuid, result text not null default 'success', metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
insert into storage.buckets (id,name,public) values ('curriculum-official','curriculum-official',false),('teacher-documents','teacher-documents',false),('exports','exports',false) on conflict (id) do nothing;
